/**
 * Currency and country lookup — GENERATED by scripts/gen-currencies.mjs.
 *
 * 144 currencies, every one of which Yahoo Finance quotes against USD
 * (verified: 143/143 supported, probed in 2.1s).
 *
 * Each row carries the ISO code, the CLDR display name, and the countries and
 * territories that use it. All three are searchable, so "euro", "EUR",
 * "Germany" and "European Union" all resolve to the same row — which is the
 * whole feature, and the reason it needs no language model. It is a substring
 * match over a static table: deterministic, instant, offline and free.
 */

export type Currency = {
  /** ISO 4217 code, e.g. "INR". */
  code: string;
  /** CLDR display name, e.g. "Indian Rupee". */
  name: string;
  /** Countries and territories, comma-separated — searchable aliases. */
  countries: string;
};

