export const CURRENCY_CODES = CURRENCIES.map((c) => c.code);

const BY_CODE = new Map(CURRENCIES.map((c) => [c.code, c]));

export const currencyByCode = (code: string): Currency | undefined =>
  BY_CODE.get(code.toUpperCase());

/**
 * Search by code, currency name, or country.
 *
 * Ranking order matters more than it looks. An exact *country alias* has to
 * outrank a name *prefix*, or "uk" returns the Ukrainian Hryvnia — "Ukrainian"
 * starts with those letters — above the British Pound, which is certainly not
 * what someone typing "uk" meant. Whole-word matches beat partial ones at
 * every tier for the same reason.
 */
export function searchCurrencies(query: string, limit = 8): Currency[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];

  const scored: Array<{ c: Currency; score: number }> = [];

  for (const c of CURRENCIES) {
    const code = c.code.toLowerCase();
    const name = c.name.toLowerCase();
    const aliases = c.countries.toLowerCase().split(", ");

    let score = 0;
    if (code === q) score = 100;
    else if (aliases.some((x) => x === q)) score = 85;
    else if (name === q) score = 82;
    else if (code.startsWith(q)) score = 80;
    else if (name.startsWith(q)) score = 75;
    else if (aliases.some((x) => x.startsWith(q))) score = 70;
    else if (name.includes(q)) score = 50;
    else if (aliases.some((x) => x.includes(q))) score = 40;

    if (score > 0) scored.push({ c, score });
  }

  return scored
    .sort((a, b) => b.score - a.score || a.c.code.localeCompare(b.c.code))
    .slice(0, limit)
    .map((s) => s.c);
}
